        points: [['議院内閣制で内閣と与党が一体であることを述べている', 3], ['官僚の専門知識による法案作成を述べている', 2], ['選挙で選ばれない官僚の主導・審議の形骸化という問題を述べている', 3], ['国会のスタッフの充実や審議の強化などの具体的な方策を示している', 2]],
